#!/usr/bin/env python3
"""Write critique/SUMMARY.json ({"html": ...}) for build-owner-page.py from the third-pass numbers in
verify-after/verify.json (after the critique fixes were deployed) and the second-pass numbers kept in
verify-after/verify-pass2.json (the render the critique looked at). Arabic, for the owner page."""
import json, os
SIM = '/home/user/ElmsNest/brief/side-pages/simplify'
A = json.load(open(f'{SIM}/verify-after/verify.json'))
P2 = json.load(open(f'{SIM}/verify-after/verify-pass2.json')) if os.path.exists(f'{SIM}/verify-after/verify-pass2.json') else {}
def sc(d, k, f='screens'): return d.get(f'{k}-m-js', {}).get(f, '—')
def atc(d, k): return d.get(f'{k}-m-js', {}).get('atcTop', '—')
rows = [
    ('كل المنتجات', 'collection-all'), ('كولكشن الممرّات', 'collection-path'), ('الرئيسية', 'home'),
    ('منتج الحبل الضوئي', 'pdp-rope'), ('منتج عمود الممرّ', 'pdp-path'), ('منتج الدرج', 'pdp-deck'),
]
tbl = ''.join(f'<tr><th>{t}</th><td>{sc(P2,k)}</td><td>{sc(A,k)}</td></tr>' for t, k in rows)
atc_rows = ''.join(f'<tr><th>{t}</th><td>{atc(P2,k)}</td><td>{atc(A,k)}</td></tr>' for t, k in rows if k.startswith('pdp'))
html = f'''
<p>أربع عدسات قرأت اللقطات الحقيقية للصفحات المنشورة على الثيم التجريبي: مشترٍ لأول مرة على هاتف، مهندس اختبار على الأرقام، حارس الصدق على النصوص والصور، وأنت — شكاواك الثلاث بحروفها. <b>34 ملاحظة</b>، وعلى كل واحدة مشكّك مستقل طُلب منه نقضها: <b>30 أُكِّدت</b> و4 نُقضت. الإصلاحات نُشرت وقِيست من جديد.</p>
<h3>ما تغيّر بعد النقد</h3>
<ul class="list">
<li><b>صور المنتجات كما هي.</b> صورك الـ27 كلها مربعة، وكانت البطاقة تقصّها بنسبة طولية فتقطع الكتابة المطبوعة عليها. البطاقة صارت مربعة: لا قصّ، ولا شيء مضاف.</li>
<li><b>اسم المنتج كاملاً.</b> 26 من 27 عنواناً كان مقطوعاً بعد سطرين («– 0…»). العنوان صار ثلاثة أسطر بحرف أصغر قليلاً، وصفحة «كل المنتجات» قصُرت مع ذلك لأن البطاقة المربعة أقصر.</li>
<li><b>زر الشراء أقرب.</b> شريط الصور المصغّرة تحت صورة المنتج على الهاتف استُبدل بعدّاد Kalles («1 / 6») — نحو مئة بكسل أقرب إلى الزر.</li>
<li><b>خطأ حقيقي وُجد وأُصلح.</b> الشيفرة التي تنسخ الخيار المختار إلى شريط الشراء الملتصق كانت تبحث عن النموذج باسم غير موجود، فلم تعمل يوماً؛ من كان يختار «12 متر» ثم يضغط زر الشريط كان سيضيف «7 متر». وقائمة الاحتياط بلا جافاسكربت كانت مربوطة بالاسم نفسه. أُصلحا معاً.</li>
<li><b>سهمان مقلوبان.</b> سهم الفرز وسهم «كل ما هو مكتوب على المنتج» كانا يشيران يساراً/يميناً في اتجاه العبرية — شكل رابط «رجوع». صارا إلى الأسفل، مع كلمة «מיון» ظاهرة قبل قائمة الفرز، وخيار «סדר החנות» بدل «מומלץ» لأن صفحة «كل المنتجات» مرتّبة أبجدياً عند Shopify لا حسب توصية.</li>
<li><b>لا تكرار في جدول المواصفات.</b> الجدول كان يعيد أطوال الحبل وألوانه التي تظهر كأزرار فوقه بشاشة واحدة؛ الصف الذي يكرّر خيارات المنتج يُحذف. و«IP65» كان يُكتب مرتين فوق بعضهما — بقيت العلامة الكبيرة وذهب التكرار.</li>
<li><b>سعر التوصيل للبيت</b> («עד הבית 29.90 ₪») أُضيف إلى سطر الشروط تحت زر الشراء — بالصيغة نفسها المكتوبة في الرئيسية.</li>
<li><b>الرئيسية:</b> عبارة «קטגוריה אחת בלבד» حُذفت (قُرئت كـ«فئة واحدة فقط» فوق أربع كولكشنات)، والعنوان الكبير صُغّر قليلاً كي يبقى على سطرين كما صُمّم.</li>
<li>أصغر: لا تسمية «سعر عرض» لقارئات الشاشة على منتجات ليست في عرض؛ شريط الصور يعمل بلا جافاسكربت على الحاسوب؛ رأس الكولكشن أقصر على الهواتف الصغيرة جداً.</li>
</ul>
<h3>الأرقام بعد الإصلاح (شاشات هاتف 390×844)</h3>
<div class="tablewrap"><table class="nums"><thead><tr><th>الصفحة</th><th>قبل النقد</th><th>بعده</th></tr></thead><tbody>{tbl}</tbody></table></div>
<p class="muted">وموضع زر الشراء من أعلى الصفحة بالبكسل (الشاشة 844):</p>
<div class="tablewrap"><table class="nums"><thead><tr><th>المنتج</th><th>قبل</th><th>بعد</th></tr></thead><tbody>{atc_rows}</tbody></table></div>
<h3>ما رفضتُه — وسؤال لك</h3>
<ul class="list">
<li><b>«الأماكن الأربعة ثلاث مرات في الرئيسية».</b> عدسة المالك قالت إن الرئيسية تعرض الكولكشنات الأربع كبلاطات ثم كأربعة صفوف «متى نعم ومتى لا». رفضتُ دمجهما: البلاطات تجيب «أين تحتاج ضوءاً؟» والصفوف تجيب «هل يناسب مكاني ومتى لا؟» بالعبارات الأربع التي وافقتَ عليها؛ الدمج يُسقط نصف «لا». <b>إن رأيتَها تكراراً، إزالة كتلة الصفوف تغيير سطر واحد.</b></li>
<li><b>زرّا شراء في صفحة المنتج.</b> الزر الأصلي وشريط ملتصق يظهر فقط بعدما يغيب الزر عن الشاشة — هو الزر نفسه يتبع الزبون، النمط الذي طلبته. بقي.</li>
<li><b>سطر الشروط يظهر في الدرج أيضاً.</b> السطر نفسه الذي قرأه الزبون للتو في صفحة المنتج، فوق المجموع مباشرة، بدل الفراغ. مكتوب مرة واحدة في الشيفرة.</li>
</ul>
'''
json.dump({'html': html}, open(f'{SIM}/critique/SUMMARY.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('SUMMARY.json written', len(html), 'chars; pass2 numbers:', 'yes' if P2 else 'MISSING')
